mapper.insert:
MERGE INTO CHB_MST_COUNTER_PARTY bbd using (
#{item.uuid,jdbcType=VARCHAR} UUID, #{item.counterId,jdbcType=VARCHAR} COUNTER_ID, #{item.counterType,jdbcType=VARCHAR} COUNTER_TYPE, #{item.counterName,jdbcType=VARCHAR} COUNTER_NAME, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.counterType2,jdbcType=VARCHAR} COUNTER_TYPE2, #{item.status,jdbcType=VARCHAR} STATUS
) datas on (bbd.COUNTER_ID = datas.COUNTER_ID ) WHEN MATCHED THEN UPDATE set bbd.COUNTER_TYPE = datas.COUNTER_TYPE, bbd.COUNTER_NAME = datas.COUNTER_NAME, bbd.REMARK = datas.REMARK, bbd.COUNTER_TYPE2 = datas.COUNTER_TYPE2, bbd.UPDATE_USER = datas.UPDATE_USER, bbd.UPDATE_TIME = datas.UPDATE_TIME WHEN NOT MATCHED THEN INSERT ( UUID,COUNTER_ID, COUNTER_TYPE,COUNTER_NAME,REMARK,CREATE_USER, CREATE_DEPT, CREATE_TIME,UPDATE_USER, UPDATE_TIME,COUNTER_TYPE2,STATUS) VALUES ( datas.UUID,datas.COUNTER_ID, datas.COUNTER_TYPE,datas.COUNTER_NAME,datas.REMARK,datas.CREATE_USER, datas.CREATE_DEPT, datas.CREATE_TIME,datas.UPDATE_USER, datas.UPDATE_TIME,datas.COUNTER_TYPE2,datas.STATUS )
